"""Turn specs/ into the Search cards and the Metasmith library, so both rungs carry one text.

    python3 generate.py --out cache/generated

Writes <out>/cards.json, <out>/data_types/bx.yml and <out>/transforms/bx/<tool>.py.
"""
from __future__ import annotations

import argparse
import json
import re
import shutil
import sys
from pathlib import Path

import yaml

HERE = Path(__file__).resolve().parent
NAMESPACE = "bx"
INTERPRETERS = {"bash": ["bash", "-euo", "pipefail"], "python": ["python"], "Rscript": ["Rscript"]}
IDENT = re.compile(r"^[a-z][a-z0-9_]*$")

TRANSFORM = '''\
# generated by research/bixbench_ladder/generate.py from specs/tools/{name}.yml -- do not hand-edit
#
{comment}
import os
import subprocess
from pathlib import Path
from metasmith.python_api import *

lib = TransformInstanceLibrary.ResolveParentLibrary(__file__)
model = Transform()
{declarations}

INPUTS = {{{inputs}}}
OUTPUTS = {{{outputs}}}
PARAMS = {params!r}
INTERPRETER = {interpreter!r}
SCRIPT = {script!r}


def protocol(context: ExecutionContext):
    env = dict(os.environ)
    for name, dep in INPUTS.items():
        env[f"IN_{{name}}"] = str(context.Input(dep).local)
    produced = {{dep: context.Output(dep).local for dep in OUTPUTS.values()}}
    for name, dep in OUTPUTS.items():
        env[f"OUT_{{name}}"] = str(produced[dep])
    for name, default in PARAMS.items():
        env[f"PARAM_{{name}}"] = str(context.params.get(f"{name}__{{name}}", default))
    Path("step_script").write_text(SCRIPT)
    code = subprocess.run([*INTERPRETER, "step_script"], env=env).returncode
    return ExecutionResult(
        manifest=[produced],
        success=code == 0 and all(p.exists() for p in produced.values()),
    )


TransformInstance(
    protocol=protocol,
    model=model,
    group_by={group_by},
    output_signature={{{signature}}},
)
'''


def load(specs: Path) -> tuple[dict, list[dict]]:
    types: dict = {}
    for p in sorted((specs / "types").glob("*.yml")):
        part = yaml.safe_load(p.read_text()) or {}
        if types.keys() & part.keys():
            sys.exit(f"{p.name}: redefines {sorted(types.keys() & part.keys())}")
        types |= part
    tools = [yaml.safe_load(p.read_text()) | {"_file": p.name} for p in sorted((specs / "tools").glob("*.yml"))]
    return types, tools


def ancestors(types: dict, name: str) -> list[str]:
    chain = [name]
    while types[chain[-1]].get("extends"):
        chain.append(types[chain[-1]]["extends"])
    return chain


def lint(types: dict, tools: list[dict]) -> list[str]:
    errors = []
    for name, t in types.items():
        if not IDENT.match(name):
            errors.append(f"type {name}: not a lower_snake identifier")
        if not t.get("description"):
            errors.append(f"type {name}: no description")
        if t.get("extends") and t["extends"] not in types:
            errors.append(f"type {name}: extends unknown type {t['extends']}")
    producer: dict[str, str] = {}
    for tool in tools:
        name = tool.get("name", tool["_file"])
        if tool["_file"] != f"{name}.yml" or not IDENT.match(name):
            errors.append(f"{tool['_file']}: name must be lower_snake and match the file name")
        for field in ("tool", "summary", "usage", "inputs", "outputs", "interpreter", "script"):
            if not tool.get(field):
                errors.append(f"{name}: missing {field}")
        if tool.get("interpreter") not in INTERPRETERS:
            errors.append(f"{name}: interpreter must be one of {sorted(INTERPRETERS)}")
        slots = {**tool.get("inputs", {}), **tool.get("outputs", {})}
        if len(slots) != len(tool.get("inputs", {})) + len(tool.get("outputs", {})):
            errors.append(f"{name}: an input and an output share a name")
        for slot, tname in slots.items():
            if not IDENT.match(slot):
                errors.append(f"{name}: slot {slot} is not a lower_snake identifier")
            if tname not in types:
                errors.append(f"{name}: slot {slot} names unknown type {tname}")
        script = tool.get("script", "")
        for slot in tool.get("inputs", {}):
            if f"IN_{slot}" not in script:
                errors.append(f"{name}: script never reads IN_{slot}")
        for slot, tname in tool.get("outputs", {}).items():
            if f"OUT_{slot}" not in script:
                errors.append(f"{name}: script never writes OUT_{slot}")
            if tname in producer:
                errors.append(f"{name}: type {tname} is already produced by {producer[tname]}")
            producer[tname] = name
            if tname in types:
                for inp in tool.get("inputs", {}).values():
                    if inp in ancestors(types, tname):
                        errors.append(f"{name}: output {tname} satisfies its own input {inp}")
        for pname, p in (tool.get("params") or {}).items():
            if not IDENT.match(pname) or "default" not in p or not p.get("help"):
                errors.append(f"{name}: param {pname} needs a lower_snake name, a default and help")
            if f"PARAM_{pname}" not in script:
                errors.append(f"{name}: script never reads PARAM_{pname}")
    return errors


def describe(types: dict, tname: str) -> str:
    t = types[tname]
    form = f".{t['ext']} file" if t.get("ext") else "directory"
    return f"{NAMESPACE}::{tname} ({form}): {t['description']}"


def card(types: dict, tool: dict) -> dict:
    lines = [f"## {tool['name']} — {tool['tool']}", tool["summary"].strip(), "", tool["usage"].strip(), "", "Inputs:"]
    lines += [f"- {slot}: {describe(types, t)}" for slot, t in tool["inputs"].items()]
    lines.append("Outputs:")
    lines += [f"- {slot}: {describe(types, t)}" for slot, t in tool["outputs"].items()]
    if tool.get("params"):
        lines.append("Parameters:")
        lines += [f"- {n} (default {p['default']!r}): {p['help']}" for n, p in tool["params"].items()]
    lines += ["", f"Reference invocation ({tool['interpreter']}; IN_*, OUT_* and PARAM_* stand for the paths and values above):",
              "```", tool["script"].strip(), "```"]
    return {"name": tool["name"], "tool": tool["tool"], "summary": tool["summary"].strip(), "text": "\n".join(lines)}


def types_yml(types: dict) -> str:
    out = {}
    for name, t in types.items():
        props = {"_": t["description"]}
        if t.get("ext"):
            props["ext"] = t["ext"]
        out[name] = {"properties": props} | ({"extends": t["extends"]} if t.get("extends") else {})
    return "# generated by research/bixbench_ladder/generate.py -- do not hand-edit\n" + yaml.safe_dump(
        {"types": out}, sort_keys=False, width=1000)


def transform(types: dict, tool: dict, text: str) -> str:
    decl = [f'{s} = model.AddRequirement(lib.GetType("{NAMESPACE}::{t}"))' for s, t in tool["inputs"].items()]
    decl += [f'{s} = model.AddProduct(lib.GetType("{NAMESPACE}::{t}"))' for s, t in tool["outputs"].items()]
    signature = ", ".join(
        f'{s}: "{s}.{types[t]["ext"]}"' if types[t].get("ext") else f'{s}: "{s}"' for s, t in tool["outputs"].items())
    return TRANSFORM.format(
        name=tool["name"],
        comment="\n".join(f"# {line}".rstrip() for line in text.splitlines()),
        declarations="\n".join(decl),
        inputs=", ".join(f'"{s}": {s}' for s in tool["inputs"]),
        outputs=", ".join(f'"{s}": {s}' for s in tool["outputs"]),
        params={n: p["default"] for n, p in (tool.get("params") or {}).items()},
        interpreter=INTERPRETERS[tool["interpreter"]],
        script=tool["script"],
        group_by=next(iter(tool["inputs"])),
        signature=signature,
    )


def main() -> None:
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--specs", type=Path, default=HERE / "specs")
    ap.add_argument("--out", type=Path, required=True)
    ap.add_argument("--lint", action="store_true", help="check the specs and write nothing")
    a = ap.parse_args()
    types, tools = load(a.specs)
    errors = lint(types, tools)
    if errors:
        sys.exit("\n".join(errors))
    if a.lint:
        print(f"{len(tools)} tools, {len(types)} types: ok")
        return
    cards = [card(types, t) for t in tools]
    for sub in ("data_types", "transforms"):
        shutil.rmtree(a.out / sub, ignore_errors=True)
    (a.out / "data_types").mkdir(parents=True)
    (a.out / "transforms" / NAMESPACE).mkdir(parents=True)
    (a.out / "cards.json").write_text(json.dumps(cards, indent=1))
    (a.out / "data_types" / f"{NAMESPACE}.yml").write_text(types_yml(types))
    for tool, c in zip(tools, cards):
        (a.out / "transforms" / NAMESPACE / f"{tool['name']}.py").write_text(transform(types, tool, c["text"]))
    print(f"{len(tools)} tools, {len(types)} types -> {a.out}")


if __name__ == "__main__":
    main()
